  access_plan := access_plan || $elk_json$[{"action":"insert","slug":"kozy-kamp-river-access","payload":{"name":"Kozy Kamp River Access","type":"gravel_bar","location_orig":{"type":"Point","coordinates":[-94.3895,36.58841]},"is_public":false,"ownership":"Elk River Floats (private)","official_site_url":"https://kozykamp.com/float-trips","facilities":"Private campground river access. Check in with the operator for parking and access arrangements.","description":"North/right bank; campground track to the water west of the highway bridge. Confirm operator-designated launch at the selected track and parking/check-in entrance. Owner screenshot approach pin is 36.588894,-94.389059, not a water-entry pin.","managing_agency":"Private","directions_override":"71 Elk River Road, Pineville, MO 64856","parking_info":"Check in with the operator. Noel and 12-mile day floaters park at Wayside; guests may have different shuttle arrangements.","road_access":"71 Elk River Road, Pineville, MO 64856","fee_required":true,"fee_notes":"Operator rental or paid river-access pass required; confirm current availability and terms.","is_float_endpoint":false,"types":["gravel_bar","campground"]}},{"action":"insert","slug":"trestle-park-river-access","payload":{"name":"Trestle Park River Access","type":"gravel_bar","location_orig":{"type":"Point","coordinates":[-94.45495,36.58521]},"is_public":false,"ownership":"Elk River Floats (private)","official_site_url":"https://trestlepark.com/elk-river-campground","facilities":"Private campground river access. Check in with the operator for parking and access arrangements.","description":"Northeast/right bank beach, immediately downstream/northwest of the Elk Springs Road low-water crossing. Confirm whether the upper-trip take-out and Noel-trip put-in use different sides of the crossing, and the operator-approved passage/walk between them. Candidate is the beach, not the cabins.","managing_agency":"Private","directions_override":"435 Elk Springs Road, Noel, MO 64854","parking_info":"Check in with the operator. Noel and 12-mile day floaters park at Wayside; guests may have different shuttle arrangements.","road_access":"435 Elk Springs Road, Noel, MO 64854","fee_required":true,"fee_notes":"Operator rental or paid river-access pass required; confirm current availability and terms.","is_float_endpoint":false,"types":["gravel_bar","campground"]}},{"action":"insert","slug":"wayside-campground-river-access","payload":{"name":"Wayside Campground River Access","type":"gravel_bar","location_orig":{"type":"Point","coordinates":[-94.49429,36.54897]},"is_public":false,"ownership":"Elk River Floats (private)","official_site_url":"https://waysidecamp.com/camping","facilities":"Private campground river access. Check in with the operator for parking and access arrangements.","description":"Southwest/left bank designated beach near the office/highway junction, upstream of the campground no-watercraft boundary. Confirm this part of the designated beach is the current trip landing and check-in parking route; do not use the peninsula tip. Shadow Lake Dam is approximately 0.3 river miles downstream of this landing candidate.","managing_agency":"Private","directions_override":"201 Minnow Springs Ave, Noel, MO 64854","parking_info":"Check in with the operator. Noel and 12-mile day floaters park at Wayside; guests may have different shuttle arrangements.","road_access":"201 Minnow Springs Ave, Noel, MO 64854","fee_required":true,"fee_notes":"Operator rental or paid river-access pass required; confirm current availability and terms.","is_float_endpoint":false,"types":["gravel_bar","campground"]}}]$elk_json$::jsonb;
  tally := public.apply_access_point_dossier(r,access_plan);
  IF tally->>'inserted' <> '3' OR tally->>'updated' <> '3' THEN RAISE EXCEPTION 'Unexpected access tally %',tally; END IF;
  -- The importer fills every null mile. Keep the excluded tributary research record unlocated on Elk.
  UPDATE public.access_points SET river_mile_downstream=NULL,river_mile_upstream=NULL WHERE river_id=r AND slug='lanagan-access' AND NOT approved AND NOT is_float_endpoint;
  UPDATE public.rivers SET float_summary='The Elk runs from Pineville through Noel, with public river accesses, gravel bars, bluffs and riverside campgrounds. Eddy shows measured Noel stage without recreational condition ratings.',float_tip='Use approved river access points. Mount Shira and Cowskin do not allow camping.',updated_at=now() WHERE id=r;
  UPDATE public.river_sections SET description='Upper Elk from Pineville through Noel above Shadow Lake Dam. Eddy plans between approved access points using river geometry; private campground listings do not establish launch eligibility.' WHERE river_id=r AND section_slug='elk-main';
  IF (SELECT count(*) FROM public.service_rivers WHERE river_id=r) <> 10 THEN RAISE EXCEPTION 'Expected ten linked services'; END IF;
  IF (SELECT count(*) FROM public.access_points WHERE river_id=r AND approved) <> 3 OR (SELECT count(*) FROM public.access_points WHERE river_id=r AND approved AND is_float_endpoint) <> 2 THEN RAISE EXCEPTION 'Published access eligibility changed'; END IF;
  IF EXISTS (SELECT 1 FROM public.access_points WHERE river_id=r AND slug IN ('kozy-kamp-river-access','trestle-park-river-access','wayside-campground-river-access') AND (approved OR is_float_endpoint)) THEN RAISE EXCEPTION 'Private candidates must remain pending'; END IF;
END $elk_inventory$;
SELECT jsonb_build_object('active',r.active,'services',(SELECT count(*) FROM public.service_rivers WHERE river_id=r.id),'approved_accesses',(SELECT count(*) FROM public.access_points WHERE river_id=r.id AND approved),'pending_private_candidates',(SELECT count(*) FROM public.access_points WHERE river_id=r.id AND slug IN ('kozy-kamp-river-access','trestle-park-river-access','wayside-campground-river-access') AND NOT approved AND NOT is_float_endpoint),'pois',(SELECT count(*) FROM public.points_of_interest WHERE river_id=r.id AND active)) AS result FROM public.rivers r WHERE slug='elk';

